<?php
declare(strict_types=1);
namespace EPejabat\Core;
/** Pure-PHP text PDF with an embedded Unicode BMP font, private images and vector QR. */
final class Pdf {
 private static function u16(string $b,int $o):int{return unpack('n',substr($b,$o,2))[1];}
 private static function u32(string $b,int $o):int{return unpack('N',substr($b,$o,4))[1];}
 private static function font():array {$bytes=file_get_contents(APP_ROOT.'/assets/fonts/DejaVuSansMono.ttf');$tables=[];for($i=0;$i<self::u16($bytes,4);$i++){$o=12+$i*16;$tables[substr($bytes,$o,4)]=self::u32($bytes,$o+8);}$c=$tables['cmap'];$fmt=null;for($i=0;$i<self::u16($bytes,$c+2);$i++){$x=$c+self::u32($bytes,$c+4+$i*8+4);if(self::u16($bytes,$x)===4)$fmt=$x;}if($fmt===null)throw new \RuntimeException('Unicode font tidak sah.');$seg=self::u16($bytes,$fmt+6)/2;$ends=$fmt+14;$starts=$ends+$seg*2+2;$deltas=$starts+$seg*2;$ranges=$deltas+$seg*2;$map=str_repeat("\0",131072);for($i=0;$i<$seg;$i++){for($cp=self::u16($bytes,$starts+$i*2),$end=self::u16($bytes,$ends+$i*2);$cp<=$end&&$cp<65535;$cp++){$delta=self::u16($bytes,$deltas+$i*2);$range=self::u16($bytes,$ranges+$i*2);$glyph=$range?self::u16($bytes,$ranges+$i*2+$range+2*($cp-self::u16($bytes,$starts+$i*2))):$cp;if($glyph)$glyph=($glyph+$delta)&65535;$map[$cp*2]=chr($glyph>>8);$map[$cp*2+1]=chr($glyph&255);}}return [$bytes,$map];}
 private static function stream(string $b,string $extra=''):string{return '<< /Length '.strlen($b).' '.$extra." >>\nstream\n".$b."\nendstream";}
 public static function generate(array $lines,array $signatures=[],?array $qr=null):string {
  [$font,$map]=self::font();$obj=[];$add=function($s)use(&$obj){$obj[]=$s;return count($obj);};$catalog=$add('');$pages=$add('');$ff=$add(self::stream(gzcompress($font),'/Filter /FlateDecode /Length1 '.strlen($font)));$descriptor=$add('<< /Type /FontDescriptor /FontName /DejaVuSansMono /Flags 33 /FontBBox [-560 -400 850 1100] /ItalicAngle 0 /Ascent 928 /Descent -236 /CapHeight 729 /StemV 80 /FontFile2 '.$ff.' 0 R >>');$cm=$add(self::stream(gzcompress($map),'/Filter /FlateDecode'));$cid=$add('<< /Type /Font /Subtype /CIDFontType2 /BaseFont /DejaVuSansMono /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor '.$descriptor.' 0 R /DW 602 /CIDToGIDMap '.$cm.' 0 R >>');$uni="/CIDInit /ProcSet findresource begin 12 dict begin begincmap /CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def /CMapName /Identity-UCS def /CMapType 2 def 1 begincodespacerange <0000> <FFFF> endcodespacerange 1 beginbfrange <0000> <FFFF> <0000> endbfrange endcmap CMapName currentdict /CMap defineresource pop end end";$uf=$add(self::stream($uni));$f=$add('<< /Type /Font /Subtype /Type0 /BaseFont /DejaVuSansMono /Encoding /Identity-H /DescendantFonts ['.$cid.' 0 R] /ToUnicode '.$uf.' 0 R >>');
  $wrapped=[];foreach($lines as $line){$line=Core::text((string)$line,10000,false);foreach(explode("\n",$line) as $paragraph){if(!$wrapped&&mb_strlen($paragraph)>50){$wrapped[]=mb_substr($paragraph,0,50);$paragraph=mb_substr($paragraph,50);}if($paragraph==='')$wrapped[]='';while(mb_strlen($paragraph)>82){$wrapped[]=mb_substr($paragraph,0,82);$paragraph=mb_substr($paragraph,82);}if($paragraph!=='')$wrapped[]=$paragraph;}}$chunks=array_chunk($wrapped?:[''],44);$imageIds=[];foreach($signatures as $i=>$s){$data=$s['bytes'];$info=@getimagesizefromstring($data);if(!$info||$info[0]>3000||$info[1]>3000||strlen($data)>5000000)throw new \RuntimeException('Signature image tidak sah.');if($info['mime']!=='image/jpeg')throw new \RuntimeException('PDF signature memerlukan JPEG; convert PNG sebelum upload.');$imageIds[$i]=$add(self::stream($data,'/Type /XObject /Subtype /Image /Width '.$info[0].' /Height '.$info[1].' /ColorSpace '.($info['channels']===1?'/DeviceGray':'/DeviceRGB').' /BitsPerComponent 8 /Filter /DCTDecode'));}
  $kids=[];foreach($chunks as $page=>$rows){$cmd="BT /F1 10 Tf 13 TL 48 790 Td\n";foreach($rows as $i=>$line){if($i)$cmd.="T* /F1 10 Tf\n";else if($page===0)$cmd.="/F1 16 Tf\n";$cmd.='<'.bin2hex(mb_convert_encoding($line,'UTF-16BE','UTF-8'))."> Tj\n";}$cmd.="ET\n";$images='';if($page===count($chunks)-1){foreach($imageIds as $i=>$image){$x=48+$i*200;$cmd.="q 140 0 0 50 $x 105 cm /I$i Do Q\n";$images.='/I'.$i.' '.$image.' 0 R ';}$cmd.="BT /F1 8 Tf 48 87 Td ";$captions=[];foreach($signatures as $s)$captions[]=$s['name'].' — '.$s['position'];$cmd.='<'.bin2hex(mb_convert_encoding(implode(' | ',$captions),'UTF-16BE','UTF-8'))."> Tj ET\n";if($qr){$n=count($qr);$scale=85/($n+8);$cmd.="0 0 0 rg\n";foreach($qr as $y=>$row)foreach($row as $x=>$on)if($on)$cmd.=sprintf('%.3F %.3F %.3F %.3F re f'."\n",465+($x+4)*$scale,105+($n-$y+3)*$scale,$scale,$scale);}}$content=$add(self::stream($cmd));$kids[]=$add('<< /Type /Page /Parent '.$pages.' 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 '.$f.' 0 R >> /XObject << '.$images.' >> >> /Contents '.$content.' 0 R >>');}
  $obj[$catalog-1]='<< /Type /Catalog /Pages '.$pages.' 0 R >>';$obj[$pages-1]='<< /Type /Pages /Kids ['.implode(' ',array_map(fn($i)=>$i.' 0 R',$kids)).'] /Count '.count($kids).' >>';$pdf="%PDF-1.7\n%\xE2\xE3\xCF\xD3\n";$offset=[0];foreach($obj as $i=>$value){$offset[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$value."\nendobj\n";}$xref=strlen($pdf);$pdf.='xref'."\n0 ".(count($obj)+1)."\n0000000000 65535 f \n";foreach(array_slice($offset,1) as $o)$pdf.=sprintf('%010d 00000 n '."\n",$o);return $pdf.'trailer'."\n<< /Size ".(count($obj)+1).' /Root '.$catalog." 0 R >>\nstartxref\n".$xref."\n%%EOF\n";
 }
}
